preConditionHook:
// THE TREND LINE USED AS A TRAILING STOP, BUT ONLY AFTER THE BREAK IS
// CONFIRMED: exit the long once the closing price has been BELOW the bull
// trend line for confirmCloses CONSECUTIVE bars, bars 0..confirmCloses-1.
// Short is the mirror above the bear line. Grimes (G08-17) leaves the
// confirmation open -- multiple closes, a consolidation under the line, or
// multiple legs under it -- and only the closes form is mechanizable;
// confirmCloses 2 is his smallest.
//
// THE LINE is the family's shared construction (merge decision 20 and the
// Brooks channel decision): the BULL trend line runs through the two most
// recent CONFIRMED swing pivot lows, the BEAR trend line through the two most
// recent confirmed swing pivot highs, and the two are deliberately NOT
// parallel. A long is stopped out by ITS OWN side's line -- the bull line it
// has been riding -- which is the opposite pairing from
// TrendLineBrokenRecently, where a long needs the BEAR line broken as
// permission to enter countertrend.
//
// NOT TrendLineBrokenRecently, twofold: that rule is K-of-N over a window of
// withinBars, this is an ALL-OF-N run of consecutive closes; and that rule is
// an ENTRY, which cannot sit in the exit pane. ConsecutiveClosesBeyondEmaRun
// beside BarsBeyondEmaCount is the corpus's precedent for keeping a run apart
// from a count. The loop runs exactly confirmCloses iterations, so the count
// reaching confirmCloses means every one of those bars closed through.
//
// confirmCloses IS GUARDED AT 1 OR MORE: at 0 the loop would not run and the
// count would trivially reach the threshold, exiting on the entry bar.
//
// COUNTED WITH AN EXPLICIT LOOP rather than CountIF, for
// TrendLineBrokenRecently's reason: CountIF's argument is a price SERIES, and
// the counted predicate here compares against a line whose value differs on
// every bar of the window.
//
// THE PIVOTS ARE THE CURRENT ONES, not the pivots as they stood at bar kk;
// re-deriving the pivot set per bar is not expressible in EL, so the line is
// re-read at each bar of the run through TLValue's free extrapolation. Same
// simplification in both twins.
//
// The pivot scan is INLINED, mirroring the twin's Occurrence 1 and 2 reads.
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR BEYOND the swingStrength OLDER bars, STRICTLY BEYOND
// the swingStrength NEWER bars, and bars-ago indexing makes the SMALLER index
// the NEWER bar, so the strict half is the k < j loop; the confirmation lag is
// exactly swingStrength bars, so j starts there; pivotLookback is EL's Length
// with offsets 0..pivotLookback-1 inclusive while the neighbourhood test
// reaches swingStrength bars PAST the window, so the deepest index the scan
// touches is pivotLookback - 1 + swingStrength; an empty window is the -1
// SENTINEL, guarded here on the BAR INDEX and never on a price; the
// comparisons carry the 2.22e-12 relational tolerance. Occurrence 3+ is
// UNMEASURED and never asked for. No WFSafe_SwingLow exists, so plain EL
// governs.
//
// MEASURED, EL_TLValue_Probe.txt: the two-point line anchored at the FIRST
// pair, Slope = (P2 - P1) / (B2 - B1); value = P1 + (target - B1) * Slope,
// extrapolating freely. Bars-ago convention, OLDER pivot as P1/B1 (the
// zero-drift spelling). Bar1 = Bar2 silently returns 0.0 and is guarded rather
// than relied on; the slope is hoisted out of the per-target arithmetic where
// the twin recomputes it inside each TLValue call -- identical doubles, same
// line -- and is computed only inside the guard.
//
// Scratch is declared in localVariables, not at hook scope, so the hooks
// survive a double placement; the loop counters and per-candidate flags are
// block-scoped. Every local is fully assigned each bar before it is read.
//
// Deepest bar touched:
// max(pivotLookback - 1 + swingStrength, confirmCloses - 1).
pivS = (int)swingStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2);
loSlope = 0.0;
hiSlope = 0.0;
if (haveLoLine) loSlope = (loP2 - loP1) / (loB2 - loB1);
if (haveHiLine) hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
belowRun = 0;
aboveRun = 0;
if (el_ge(confirmCloses, 1.0)) {
    for (int kk = 0; kk <= (int)confirmCloses - 1; ++kk) {
        if (haveLoLine && el_lt(close[kk], loP1 + ((double)kk - loB1) * loSlope)) {
            belowRun = belowRun + 1;
        }
        if (haveHiLine && el_gt(close[kk], hiP1 + ((double)kk - hiB1) * hiSlope)) {
            aboveRun = aboveRun + 1;
        }
    }
}
